# English Korean-reading guide: dictionary first, no garbage letter-by-letter fallback
old = '''    private String englishPronunciation(String text) {\n        String key = text.trim().toLowerCase(Locale.ROOT).replaceAll("\\\\s+", " ");\n        switch (key) {\n            case "hello": return "헬로";\n            case "thank you":\n            case "thank you.": return "땡큐";\n            case "how much is it?":\n            case "how much is it": return "하우 머치 이즈 잇?";\n            case "where is it?":\n            case "where is it": return "웨어 이즈 잇?";\n            case "please help me":\n            case "please help me.": return "플리즈 헬프 미";\n            case "where is the restroom?":\n            case "where is the restroom": return "웨어 이즈 더 레스트룸?";\n            default: return pronounceWords(text, false);\n        }\n    }'''
new = '''    private String englishPronunciation(String text) {\n        String key = text.trim().toLowerCase(Locale.ROOT).replaceAll("\\\\s+", " ");\n        switch (key) {\n            case "hello": return "헬로";\n            case "nice to meet you":\n            case "nice to meet you.": return "나이스 투 미트 유";\n            case "thank you":\n            case "thank you.": return "땡큐";\n            case "how much is it?":\n            case "how much is it": return "하우 머치 이즈 잇?";\n            case "where is it?":\n            case "where is it": return "웨어 이즈 잇?";\n            case "please help me":\n            case "please help me.": return "플리즈 헬프 미";\n            case "where is the restroom?":\n            case "where is the restroom": return "웨어 이즈 더 레스트룸?";\n            case "i would like this": return "아이 우드 라이크 디스";\n            case "can you help me?":\n            case "can you help me": return "캔 유 헬프 미?";\n            default: return pronounceEnglishKnownWords(text);\n        }\n    }\n\n    private String pronounceEnglishKnownWords(String text) {\n        String[] words = text.trim().split("\\\\s+");\n        StringBuilder out = new StringBuilder();\n        for (String token : words) {\n            if (token.isEmpty()) continue;\n            String punctuation = token.endsWith("?") ? "?" : token.endsWith("!") ? "!" : token.endsWith(".") ? "." : token.endsWith(",") ? "," : "";\n            String core = token.replaceAll("[^\\\\p{L}']", "").toLowerCase(Locale.ROOT);\n            if (core.isEmpty()) continue;\n            String spoken = pronounceEnglishWord(core);\n            if (spoken == null || spoken.isEmpty()) return "";\n            if (out.length() > 0) out.append(' ');\n            out.append(spoken).append(punctuation);\n        }\n        return out.toString();\n    }'''
if old not in s:
    raise SystemExit('english pronunciation anchor missing')
s = s.replace(old, new, 1)

start = s.index('    private String pronounceEnglishWord(String word) {')
end = s.index('    private String englishFallback(String word) {', start)
known_words = '''    private String pronounceEnglishWord(String word) {\n        String w = word.toLowerCase(Locale.ROOT);\n        switch (w) {\n            case "hello": return "헬로";\n            case "nice": return "나이스";\n            case "to": return "투";\n            case "meet": return "미트";\n            case "thank": return "땡크";\n            case "thanks": return "땡크스";\n            case "you": return "유";\n            case "how": return "하우";\n            case "much": return "머치";\n            case "is": return "이즈";\n            case "it": return "잇";\n            case "where": return "웨어";\n            case "what": return "왓";\n            case "when": return "웬";\n            case "why": return "와이";\n            case "please": return "플리즈";\n            case "help": return "헬프";\n            case "me": return "미";\n            case "the": return "더";\n            case "restroom": return "레스트룸";\n            case "toilet": return "토일렛";\n            case "hotel": return "호텔";\n            case "airport": return "에어포트";\n            case "taxi": return "택시";\n            case "station": return "스테이션";\n            case "restaurant": return "레스토랑";\n            case "water": return "워터";\n            case "food": return "푸드";\n            case "coffee": return "커피";\n            case "beer": return "비어";\n            case "money": return "머니";\n            case "cash": return "캐시";\n            case "card": return "카드";\n            case "price": return "프라이스";\n            case "cheap": return "칩";\n            case "expensive": return "익스펜시브";\n            case "left": return "레프트";\n            case "right": return "라이트";\n            case "straight": return "스트레이트";\n            case "stop": return "스탑";\n            case "yes": return "예스";\n            case "no": return "노";\n            case "okay":\n            case "ok": return "오케이";\n            case "sorry": return "쏘리";\n            case "one": return "원";\n            case "two": return "투";\n            case "three": return "쓰리";\n            case "four": return "포";\n            case "five": return "파이브";\n            case "six": return "식스";\n            case "seven": return "세븐";\n            case "eight": return "에이트";\n            case "nine": return "나인";\n            case "ten": return "텐";\n            case "i": return "아이";\n            case "would": return "우드";\n            case "like": return "라이크";\n            case "this": return "디스";\n            case "can": return "캔";\n            case "a": return "어";\n            case "my": return "마이";\n            case "your": return "유어";\n            case "room": return "룸";\n            case "reservation": return "레저베이션";\n            case "check": return "체크";\n            case "in": return "인";\n            case "out": return "아웃";\n            case "bill": return "빌";\n            case "menu": return "메뉴";\n            case "spicy": return "스파이시";\n            case "not": return "낫";\n            default: return null;\n        }\n    }\n\n'''
