wallet_block = '''    // ---------- 내 지갑 ----------\n    private void showWallet(){\n        if(!beginToolNavigation()) return;\n        if(wallet.startingAmount()<=0){showWalletSetup();return;}\n\n        LinearLayout root=dialogRoot();\n        root.setPadding(dp(14), dp(4), dp(14), dp(12));\n\n        LinearLayout balanceCard=col();\n        balanceCard.setPadding(dp(16),dp(14),dp(16),dp(14));\n        balanceCard.setBackground(gradient(new int[]{Color.rgb(245,243,255),Color.rgb(239,246,255)},dp(18)));\n        TextView balanceLabel=text("현재 잔액",13,true,PRIMARY);\n        TextView balanceValue=text("",30,true,INK);\n        TextView balanceKrw=text("",14,false,MUTED);\n        balanceCard.addView(balanceLabel);\n        balanceCard.addView(balanceValue,topMargin(dp(3)));\n        balanceCard.addView(balanceKrw,topMargin(dp(3)));\n        root.addView(balanceCard);\n\n        LinearLayout stats=row(Gravity.CENTER_VERTICAL);\n        LinearLayout todayCard=miniStatCard("오늘 사용");\n        LinearLayout totalCard=miniStatCard("총 사용");\n        TextView todayValue=(TextView)todayCard.getChildAt(1);\n        TextView totalValue=(TextView)totalCard.getChildAt(1);\n        stats.addView(todayCard,new LinearLayout.LayoutParams(0,dp(68),1f));\n        LinearLayout.LayoutParams totalLp=new LinearLayout.LayoutParams(0,dp(68),1f);\n        totalLp.setMargins(dp(8),0,0,0);\n        stats.addView(totalCard,totalLp);\n        root.addView(stats,topMargin(dp(9)));\n\n        TextView startInfo=text("",12,false,MUTED);\n        root.addView(startInfo,topMargin(dp(7)));\n\n        TextView addTitle=text("소비 기록",16,true,INK);\n        root.addView(addTitle,topMargin(dp(14)));\n        EditText amount=moneyInput("사용 금액 (VND)");\n        root.addView(amount,topMargin(dp(7)));\n\n        LinearLayout quick=row(Gravity.CENTER_VERTICAL);\n        long[] quickValues={50000,100000,200000,500000};\n        for(long v:quickValues){\n            Button b=compactButton(shortVnd(v),SOFT,INK);\n            b.setTextSize(13);\n            b.setOnClickListener(x->amount.setText(String.valueOf(v)));\n            quick.addView(b,new LinearLayout.LayoutParams(0,dp(36),1f));\n        }\n        root.addView(quick,topMargin(dp(6)));\n\n        EditText memo=new EditText(this);\n        memo.setHint("메모  예: 쌀국수, 택시, 마사지");\n        memo.setSingleLine(true);\n        memo.setTextSize(15);\n        memo.setBackground(roundedStroke(Color.WHITE,LINE,dp(14),1));\n        memo.setPadding(dp(12),0,dp(12),0);\n        root.addView(memo,new LinearLayout.LayoutParams(-1,dp(48)));\n\n        Button add=primaryButton("＋  소비 기록",PRIMARY);\n        root.addView(add,topMargin(dp(7)));\n\n        LinearLayout historyHeader=row(Gravity.CENTER_VERTICAL);\n        TextView historyTitle=text("최근 사용내역",16,true,INK);\n        TextView historyHint=text("최신순",12,false,MUTED);\n        historyHeader.addView(historyTitle,new LinearLayout.LayoutParams(0,-2,1f));\n        historyHeader.addView(historyHint);\n        root.addView(historyHeader,topMargin(dp(14)));\n\n        ScrollView sv=new ScrollView(this);\n        LinearLayout list=col();\n        sv.addView(list);\n        root.addView(sv,new LinearLayout.LayoutParams(-1,dp(220)));\n\n        Button settings=compactButton("여행 지갑 설정",SOFT,MUTED);\n        settings.setTextSize(13);\n        root.addView(settings,topMargin(dp(8)));\n\n        AlertDialog d=new AlertDialog.Builder(this).setTitle("👛 내 지갑").setView(root).setNegativeButton("닫기",null).create();\n        Runnable render=()->renderWalletDashboard(balanceValue,balanceKrw,todayValue,totalValue,startInfo,list);\n\n        add.setOnClickListener(v->{\n            long a=parseMoney(amount.getText().toString());\n            if(a<=0){toast("사용 금액을 입력해주세요.");return;}\n            wallet.addExpense(a,memo.getText().toString());\n            amount.setText("");\n            memo.setText("");\n            render.run();\n        });\n        settings.setOnClickListener(v->showWalletSettings(d));\n        render.run();\n        trackToolDialog(d);\n        d.show();\n    }\n\n    private LinearLayout miniStatCard(String title){\n        LinearLayout card=col();\n        card.setPadding(dp(12),dp(9),dp(12),dp(8));\n        card.setBackground(roundedStroke(Color.WHITE,LINE,dp(14),1));\n        card.addView(text(title,12,false,MUTED));\n        card.addView(text("0₫",17,true,INK),topMargin(dp(2)));\n        return card;\n    }\n\n    private void showWalletSettings(AlertDialog parent){\n        String[] items={"시작 금액 변경","여행 종료 · 지갑 초기화"};\n        new AlertDialog.Builder(this).setTitle("여행 지갑 설정").setItems(items,(dialog,which)->{\n            if(which==0){\n                EditText e=moneyInput("새 시작 금액 (VND)");\n                e.setText(String.valueOf(wallet.startingAmount()));\n                new AlertDialog.Builder(this).setTitle("시작 금액 변경").setView(e).setNegativeButton("취소",null).setPositiveButton("저장",(x,y)->{\n                    long a=parseMoney(e.getText().toString());\n                    if(a<=0){toast("금액을 확인해주세요.");return;}\n                    wallet.setStartingAmount(a);\n                    if(parent!=null) parent.dismiss();\n                    handler.postDelayed(()->{if(isActivityUsable())showWallet();},180);\n                }).show();\n            }else{\n                new AlertDialog.Builder(this).setTitle("여행을 종료할까요?").setMessage("시작 금액과 모든 소비 이력이 삭제됩니다.").setNegativeButton("취소",null).setPositiveButton("초기화",(x,y)->{\n                    wallet.resetTrip();\n                    if(parent!=null) parent.dismiss();\n                    toast("지갑을 초기화했습니다.");\n                }).show();\n            }\n        }).show();\n    }\n\n    private void showWalletSetup(){\n        LinearLayout root=dialogRoot();\n        root.addView(text("여행 시작 금액을 한 번만 입력하면 소비할 때마다 자동으로 잔액을 계산합니다.",14,false,MUTED));\n        EditText e=moneyInput("처음 가지고 있는 베트남 돈 (VND)");\n        root.addView(e,topMargin(dp(10)));\n        LinearLayout quick=row(Gravity.CENTER_VERTICAL);\n        long[] values={1000000,3000000,5000000,10000000};\n        for(long v:values){\n            Button b=compactButton(shortVnd(v),SOFT,INK);\n            b.setTextSize(13);\n            b.setOnClickListener(x->e.setText(String.valueOf(v)));\n            quick.addView(b,new LinearLayout.LayoutParams(0,dp(38),1f));\n        }\n        root.addView(quick,topMargin(dp(7)));\n        AlertDialog d=new AlertDialog.Builder(this).setTitle("👛 내 지갑 시작").setView(root).setNegativeButton("취소",null).setPositiveButton("시작하기",null).create();\n        d.setOnShowListener(x->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{\n            long a=parseMoney(e.getText().toString());\n            if(a<=0){toast("시작 금액을 입력해주세요.");return;}\n            wallet.setStartingAmount(a);\n            d.dismiss();\n            handler.postDelayed(()->{if(isActivityUsable())showWallet();},180);\n        }));\n        trackToolDialog(d);\n        d.show();\n    }\n\n    private void renderWalletDashboard(TextView balanceValue,TextView balanceKrw,TextView todayValue,TextView totalValue,TextView startInfo,LinearLayout list){\n        long start=wallet.startingAmount(), spent=wallet.spent(), balance=wallet.balance(), today=wallet.todaySpent();\n        balanceValue.setText(formatVnd(balance));\n        balanceValue.setTextColor(balance<0?RED:INK);\n        balanceKrw.setText("약 "+formatKrw(Math.max(0,balance)*fx.rateToKrw())+" · 저장 환율 기준");\n        todayValue.setText(formatVnd(today));\n        totalValue.setText(formatVnd(spent));\n        startInfo.setText("시작 "+formatVnd(start)+" · 남은 비율 "+wallet.remainingPercent()+"%");\n        list.removeAllViews();\n        List<WalletStore.Expense> items=wallet.expenses();\n        int shown=0;\n        for(int i=items.size()-1;i>=0 && shown<12;i--,shown++){\n            WalletStore.Expense ex=items.get(i); int index=i;\n            LinearLayout row=row(Gravity.CENTER_VERTICAL);\n            row.setPadding(dp(11),dp(9),dp(7),dp(9));\n            row.setBackground(roundedStroke(Color.WHITE,LINE,dp(12),1));\n            LinearLayout txt=col();\n            txt.addView(text(ex.memo.isEmpty()?"소비":ex.memo,14,true,INK));\n            txt.addView(text(WalletStore.when(ex.time),12,false,MUTED),topMargin(dp(2)));\n            row.addView(txt,new LinearLayout.LayoutParams(0,-2,1f));\n            row.addView(text("-"+formatVnd(ex.amount),14,true,RED));\n            Button del=compactButton("×",SOFT,MUTED);\n            LinearLayout.LayoutParams dl=new LinearLayout.LayoutParams(dp(36),dp(34)); dl.setMargins(dp(6),0,0,0);\n            row.addView(del,dl);\n            del.setOnClickListener(v->{wallet.removeExpense(index);renderWalletDashboard(balanceValue,balanceKrw,todayValue,totalValue,startInfo,list);});\n            list.addView(row,topMargin(dp(6)));\n        }\n        if(items.isEmpty()){\n            TextView empty=text("아직 소비 이력이 없습니다.\\n사용 금액을 기록하면 여기에 바로 쌓입니다.",14,false,MUTED);\n            empty.setGravity(Gravity.CENTER); empty.setPadding(0,dp(24),0,dp(24)); list.addView(empty);\n        }\n    }\n\n'''
