old = 'private String shortVnd(long v){return v>=1000?(v/1000)+"K":String.valueOf(v);}'
new = 'private String shortVnd(long v){return v>=1000000?(v/1000000)+"M":v>=1000?(v/1000)+"K":String.valueOf(v);}'
