w = wallet.read_text()
anchor = '''    public long spent() {\n        long s = 0;\n        for (Expense e : expenses()) s += e.amount;\n        return s;\n    }\n\n'''
addition = anchor + '''    public long todaySpent() {\n        java.util.Calendar now = java.util.Calendar.getInstance();\n        int year = now.get(java.util.Calendar.YEAR);\n        int day = now.get(java.util.Calendar.DAY_OF_YEAR);\n        long s = 0;\n        for (Expense e : expenses()) {\n            java.util.Calendar c = java.util.Calendar.getInstance();\n            c.setTimeInMillis(e.time);\n            if (c.get(java.util.Calendar.YEAR) == year && c.get(java.util.Calendar.DAY_OF_YEAR) == day) s += e.amount;\n        }\n        return s;\n    }\n\n    public int remainingPercent() {\n        long start = startingAmount();\n        if (start <= 0) return 0;\n        long balance = Math.max(0, balance());\n        return (int)Math.max(0, Math.min(100, Math.round(balance * 100.0 / start)));\n    }\n\n'''
if anchor not in w:
    raise SystemExit('WalletStore anchor missing')
w = w.replace(anchor, addition, 1)
wallet.write_text(w)

